// gtav - call-count probe over every function in the XDK D3D runtime region.
//
// Used to name D3D functions in the stripped TU27 image: each probed function records its
// call count, a few distinct callers and the arguments of its first call. With
// --gtav_d3d_probe=true the table is written to logs/d3d_probe.csv every 10 s (frames from
// the Swap hook in stats_hooks.cpp give calls per frame). The list is generated by
// tools/native/gen_probe.py.

#include <rex/cvar.h>
#include <rex/hook.h>
#include <rex/logging.h>

#include <atomic>
#include <chrono>
#include <cstdint>
#include <cstdio>
#include <cstdlib>
#include <mutex>
#include <string>

#include <filesystem>

#include "paths.h"

#include "safe_read.h"

REXCVAR_DEFINE_BOOL(gtav_d3d_probe, false, "GTAV", "Count calls to every D3D runtime function");

namespace gtav::native {
void ProbeFrame();
}

namespace {

#define GTAV_PROBE(addr, index)
#include "d3d_probe_list.inc"
#undef GTAV_PROBE

constexpr int kCallers = 4;

struct Probe {
  uint32_t addr = 0;
  std::atomic<uint64_t> calls{0};
  std::atomic<uint32_t> callers[kCallers]{};
  std::atomic<bool> sampled{false};
  uint32_t args[6]{};
  double f1 = 0;
  std::atomic<uint32_t> checks{0};
  std::atomic<uint32_t> shader_args{0};  // bit i: r(3+i) pointed at a 0x102A11xx shader container
};

constexpr uint32_t kMagicChecks = 64;  // first calls of each function get their pointer args checked

// Reads a big-endian guest dword without faulting on unmapped memory.
bool SafeRead32(const uint8_t* base, uint32_t addr, uint32_t* out) {
  if (addr < 0x10000) return false;
  uint8_t b[4];
#ifdef _WIN32
  SIZE_T got = 0;
  if (!ReadProcessMemory(GetCurrentProcess(), base + addr, b, 4, &got) || got != 4) return false;
#else
  if (!gtav::native::SafeReadMemory(b, base + addr, 4)) return false;
#endif
  *out = uint32_t(b[0]) << 24 | b[1] << 16 | b[2] << 8 | b[3];
  return true;
}

Probe g_probes[GTAV_PROBE_COUNT];
std::atomic<uint64_t> g_frames{0};

void Hit(int index, uint32_t addr, PPCContext& ctx, const uint8_t* base) {
  Probe& p = g_probes[index];
  p.addr = addr;
  p.calls.fetch_add(1, std::memory_order_relaxed);
  uint32_t lr = uint32_t(ctx.lr);
  for (auto& c : p.callers) {
    uint32_t cur = c.load(std::memory_order_relaxed);
    if (cur == lr) break;
    if (cur == 0) {
      uint32_t expected = 0;
      if (c.compare_exchange_strong(expected, lr) || expected == lr) break;
    }
  }
  if (!p.sampled.exchange(true)) {
    uint32_t a[6] = {ctx.r3.u32, ctx.r4.u32, ctx.r5.u32, ctx.r6.u32, ctx.r7.u32, ctx.r8.u32};
    std::copy(a, a + 6, p.args);
    p.f1 = ctx.f1.f64;
  }
  if (p.checks.load(std::memory_order_relaxed) < kMagicChecks) {
    p.checks.fetch_add(1, std::memory_order_relaxed);
    const uint32_t regs[6] = {ctx.r3.u32, ctx.r4.u32, ctx.r5.u32, ctx.r6.u32, ctx.r7.u32, ctx.r8.u32};
    for (int i = 0; i < 6; i++) {
      uint32_t w;
      if (SafeRead32(base, regs[i], &w) && (w & 0xFFFFFF00) == 0x102A1100)
        p.shader_args.fetch_or(1u << i, std::memory_order_relaxed);
    }
  }
}

void Dump() {
  std::string path = gtav::native::LogPath("d3d_probe.csv");
  std::filesystem::create_directories(std::filesystem::path(path).parent_path());
  FILE* f = std::fopen(path.c_str(), "w");
  if (!f) return;
  uint64_t frames = g_frames.load();
  std::fprintf(f, "addr,calls,per_frame,callers,r3,r4,r5,r6,r7,r8,f1,shader_args\n");
  for (auto& p : g_probes) {
    uint64_t n = p.calls.load();
    if (!n) continue;
    std::fprintf(f, "%08X,%llu,%.2f,", p.addr, (unsigned long long)n, frames ? double(n) / frames : 0.0);
    for (auto& c : p.callers)
      if (uint32_t v = c.load()) std::fprintf(f, "%08X ", v);
    std::fprintf(f, ",%08X,%08X,%08X,%08X,%08X,%08X,%g,%X\n", p.args[0], p.args[1], p.args[2], p.args[3],
                 p.args[4], p.args[5], p.f1, p.shader_args.load());
  }
  std::fprintf(f, "# frames=%llu\n", (unsigned long long)frames);
  std::fclose(f);
}

}  // namespace

void gtav::native::ProbeFrame() {
  if (!REXCVAR_GET(gtav_d3d_probe)) return;
  using Clock = std::chrono::steady_clock;
  static Clock::time_point last = Clock::now();
  g_frames.fetch_add(1, std::memory_order_relaxed);
  if (Clock::now() - last > std::chrono::seconds(10)) {
    last = Clock::now();
    Dump();
  }
}

#define GTAV_PROBE(addr, index)                                  \
  REX_EXTERN(__imp__sub_##addr);                                 \
  REX_HOOK_RAW(sub_##addr) {                                     \
    if (REXCVAR_GET(gtav_d3d_probe)) Hit(index, 0x##addr, ctx, base);  \
    __imp__sub_##addr(ctx, base);                                \
  }
#include "d3d_probe_list.inc"
#undef GTAV_PROBE
